/* =========================================================================
   CINEMATIC FOOTER STYLE OVERLAYS
   ========================================================================= */
.cinematic-footer-wrapper {
  font-family: var(--font-plus-jakarta-sans), sans-serif;
  -webkit-font-smoothing: antialiased;
  will-change: transform;
  transform: translateZ(0);
  backface-visibility: hidden;

  --pill-bg-1: color-mix(in oklch, var(--foreground, #09090b) 3%, transparent);
  --pill-bg-2: color-mix(in oklch, var(--foreground, #09090b) 1%, transparent);
  --pill-shadow: color-mix(in oklch, var(--background, #fafafa) 50%, transparent);
  --pill-highlight: color-mix(in oklch, var(--foreground, #09090b) 10%, transparent);
  --pill-inset-shadow: color-mix(in oklch, var(--background, #fafafa) 80%, transparent);
  --pill-border: color-mix(in oklch, var(--foreground, #09090b) 8%, transparent);

  --pill-bg-1-hover: color-mix(in oklch, var(--foreground, #09090b) 8%, transparent);
  --pill-bg-2-hover: color-mix(in oklch, var(--foreground, #09090b) 2%, transparent);
  --pill-border-hover: color-mix(in oklch, var(--foreground, #09090b) 20%, transparent);
  --pill-shadow-hover: color-mix(in oklch, var(--background, #fafafa) 70%, transparent);
  --pill-highlight-hover: color-mix(in oklch, var(--foreground, #09090b) 20%, transparent);
}

@keyframes footer-breathe {
  0%   { transform: translate(-50%, -50%) scale(1);   opacity: 0.6; }
  100% { transform: translate(-50%, -50%) scale(1.1); opacity: 1;   }
}

@keyframes footer-scroll-marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

@keyframes footer-heartbeat {
  0%, 100% { transform: scale(1);   filter: drop-shadow(0 0 5px rgba(239,68,68,0.5));  }
  15%, 45% { transform: scale(1.2); filter: drop-shadow(0 0 10px rgba(239,68,68,0.8)); }
  30%      { transform: scale(1); }
}

.animate-footer-breathe       { animation: footer-breathe 8s ease-in-out infinite alternate; }
.animate-footer-scroll-marquee { animation: footer-scroll-marquee 40s linear infinite; }
.animate-footer-heartbeat      { animation: footer-heartbeat 2s cubic-bezier(0.25, 1, 0.5, 1) infinite; }

.footer-bg-grid {
  background-size: 60px 60px;
  background-image:
    linear-gradient(to right,  color-mix(in oklch, var(--foreground, #09090b) 3%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in oklch, var(--foreground, #09090b) 3%, transparent) 1px, transparent 1px);
  mask-image: linear-gradient(to bottom, transparent, black 30%, black 70%, transparent);
  -webkit-mask-image: linear-gradient(to bottom, transparent, black 30%, black 70%, transparent);
}

.footer-aurora {
  background: radial-gradient(
    circle at 50% 50%,
    rgba(109, 84, 255, 0.12) 0%,
    rgba(94, 172, 245, 0.10) 40%,
    transparent 70%
  );
}

.footer-glass-pill {
  background: linear-gradient(145deg, var(--pill-bg-1) 0%, var(--pill-bg-2) 100%);
  box-shadow:
    0 10px 30px -10px var(--pill-shadow),
    inset 0 1px 1px var(--pill-highlight),
    inset 0 -1px 2px var(--pill-inset-shadow);
  border: 1px solid var(--pill-border);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.footer-glass-pill:hover {
  background: linear-gradient(145deg, var(--pill-bg-1-hover) 0%, var(--pill-bg-2-hover) 100%);
  border-color: var(--pill-border-hover);
  box-shadow:
    0 20px 40px -10px var(--pill-shadow-hover),
    inset 0 1px 1px var(--pill-highlight-hover);
}

.footer-giant-bg-text {
  font-size: clamp(5rem, 24vw, 24rem);
  line-height: 0.75;
  font-weight: 900;
  letter-spacing: -0.05em;
  color: transparent;
  -webkit-text-stroke: 1.5px color-mix(in oklch, var(--foreground, #09090b) 12%, transparent);
  background: linear-gradient(180deg, color-mix(in oklch, var(--foreground, #09090b) 15%, transparent) 0%, transparent 75%);
  -webkit-background-clip: text;
  background-clip: text;
  bottom: -2.5vw !important;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0) 95%);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0) 95%);
}

@media (max-width: 768px) {
  .footer-giant-bg-text {
    font-size: clamp(4rem, 24vw, 10rem);
    bottom: -2.5vw !important;
    background: linear-gradient(180deg, color-mix(in oklch, var(--foreground, #09090b) 15%, transparent) 0%, transparent 88%);
    -webkit-background-clip: text;
    background-clip: text;
    mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 1) 30%, rgba(0, 0, 0, 0) 98%);
    -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 1) 30%, rgba(0, 0, 0, 0) 98%);
  }
}

.footer-text-glow {
  background: linear-gradient(
    180deg,
    var(--foreground, #09090b) 0%,
    color-mix(in oklch, var(--foreground, #09090b) 40%, transparent) 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  filter: drop-shadow(0 0 20px color-mix(in oklch, var(--foreground, #09090b) 15%, transparent));
}


/* Hide native cursor for precise-pointer devices */
@media (pointer: fine) {
  body {
    cursor: none;
  }
}

@keyframes marquee-down {
  0% {
    transform: translateY(var(--marquee-translate, -25%));
  }
  100% {
    transform: translateY(0);
  }
}
